// 30-й джуз: арабский текст Tanzil и перевод смыслов «Калям Шариф» (ДУМ РТ).
const JUZ30_SURAHS = [{"number":78,"name":"Ан-Наба","meaning":"Весть","arabicName":"النَّبَإِ","ayahs":[{"number":1,"arabic":"عَمَّ يَتَسَآءَلُونَ","russian":"О чем они [неверующие] спрашивают друг друга?"},{"number":2,"arabic":"عَنِ ٱلنَّبَإِ ٱلْعَظِيمِ","russian":"О великой вести [относительно воскрешения и вечной жизни],"},{"number":3,"arabic":"ٱلَّذِى هُمْ فِيهِ مُخْتَلِفُونَ","russian":"о которой они расходятся во мнениях [одни полностью отрицают вечную жизнь, другие сомневаются в ней]."},{"number":4,"arabic":"كَلَّا سَيَعْلَمُونَ","russian":"Но нет, [умерев] они узнают [правду]!"},{"number":5,"arabic":"ثُمَّ كَلَّا سَيَعْلَمُونَ","russian":"Еще раз нет, они узнают!"},{"number":6,"arabic":"أَلَمْ نَجْعَلِ ٱلْأَرْضَ مِهَٰدًۭا","russian":"Разве Мы не сделали землю ложем?"},{"number":7,"arabic":"وَٱلْجِبَالَ أَوْتَادًۭا","russian":"А горы – кольями?"},{"number":8,"arabic":"وَخَلَقْنَٰكُمْ أَزْوَٰجًۭا","russian":"И Мы сотворили вас парами."},{"number":9,"arabic":"وَجَعَلْنَا نَوْمَكُمْ سُبَاتًۭا","russian":"А ваш сон Мы сделали покоем."},{"number":10,"arabic":"وَجَعَلْنَا ٱلَّيْلَ لِبَاسًۭا","russian":"И сделали ночь одеянием [тьмой, окутывающей предметы]."},{"number":11,"arabic":"وَجَعَلْنَا ٱلنَّهَارَ مَعَاشًۭا","russian":"И Мы сделали день жизнью [временем добывания пропитания]."},{"number":12,"arabic":"وَبَنَيْنَا فَوْقَكُمْ سَبْعًۭا شِدَادًۭا","russian":"И Мы построили над вами семь [небес в виде семи] твердынь."},{"number":13,"arabic":"وَجَعَلْنَا سِرَاجًۭا وَهَّاجًۭا","russian":"И Мы сотворили [солнце, будто] пылающий светильник."},{"number":14,"arabic":"وَأَنزَلْنَا مِنَ ٱلْمُعْصِرَٰتِ مَآءًۭ ثَجَّاجًۭا","russian":"И Мы низвели из туч [обильно] льющуюся воду."},{"number":15,"arabic":"لِّنُخْرِجَ بِهِۦ حَبًّۭا وَنَبَاتًۭا","russian":"[Низвели] Чтобы вывести [из земли] зерна, и растения,"},{"number":16,"arabic":"وَجَنَّٰتٍ أَلْفَافًا","russian":"и густые сады."},{"number":17,"arabic":"إِنَّ يَوْمَ ٱلْفَصْلِ كَانَ مِيقَٰتًۭا","russian":"Поистине, День разделения [истины и лжи, то есть Судный день] уже имеет [установленный Аллахом] срок."},{"number":18,"arabic":"يَوْمَ يُنفَخُ فِى ٱلصُّورِ فَتَأْتُونَ أَفْوَاجًۭا","russian":"В этот день затрубят в Рог [земному миру придет конец], и вы [восстанете из могил и] придете группами."},{"number":19,"arabic":"وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتْ أَبْوَٰبًۭا","russian":"И небо раскроется и окажется воротами [из которых выйдет множество ангелов]."},{"number":20,"arabic":"وَسُيِّرَتِ ٱلْجِبَالُ فَكَانَتْ سَرَابًا","russian":"И горы будут приведены в движение [разрушатся] и станут миражом."},{"number":21,"arabic":"إِنَّ جَهَنَّمَ كَانَتْ مِرْصَادًۭا","russian":"Поистине, Ад – это засада [откуда выйдут стражи Ада и будут хватать неверующих]."},{"number":22,"arabic":"لِّلطَّٰغِينَ مَـَٔابًۭا","russian":"И [это] прибежище для [неверующих и непрощенных] грешников."},{"number":23,"arabic":"لَّٰبِثِينَ فِيهَآ أَحْقَابًۭا","russian":"Они останутся там на века [вечные]."},{"number":24,"arabic":"لَّا يَذُوقُونَ فِيهَا بَرْدًۭا وَلَا شَرَابًا","russian":"Они не вкусят [там] ни прохлады, ни питья,"},{"number":25,"arabic":"إِلَّا حَمِيمًۭا وَغَسَّاقًۭا","russian":"а только кипяток и гной."},{"number":26,"arabic":"جَزَآءًۭ وِفَاقًا","russian":"Это будет [для них] подобающим воздаянием."},{"number":27,"arabic":"إِنَّهُمْ كَانُوا۟ لَا يَرْجُونَ حِسَابًۭا","russian":"Поистине, они не готовились к отчету [за свои слова и поступки]."},{"number":28,"arabic":"وَكَذَّبُوا۟ بِـَٔايَٰتِنَا كِذَّابًۭا","russian":"И они настойчиво отрицали Наши знамения."},{"number":29,"arabic":"وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ كِتَٰبًۭا","russian":"Мы же все охватили [знанием] и записали [в Хранимой книге]."},{"number":30,"arabic":"فَذُوقُوا۟ فَلَن نَّزِيدَكُمْ إِلَّا عَذَابًا","russian":"[Неверующим, горящим в Аду, будет сказано] А теперь вкушайте [заслуженную кару]! Мы не прибавим вам ничего, кроме наказания."},{"number":31,"arabic":"إِنَّ لِلْمُتَّقِينَ مَفَازًا","russian":"Поистине, богобоязненным – спасение [и Рай],"},{"number":32,"arabic":"حَدَآئِقَ وَأَعْنَٰبًۭا","russian":"сады и виноградники,"},{"number":33,"arabic":"وَكَوَاعِبَ أَتْرَابًۭا","russian":"и сформировавшиеся девушки-сверстницы [все в возрасте шестнадцати лет],"},{"number":34,"arabic":"وَكَأْسًۭا دِهَاقًۭا","russian":"и полная чаша [с райским вином]."},{"number":35,"arabic":"لَّا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا كِذَّٰبًۭا","russian":"Они не услышат там ни пустословия, ни лжи."},{"number":36,"arabic":"جَزَآءًۭ مِّن رَّبِّكَ عَطَآءً حِسَابًۭا","russian":"[Все это –] Воздаяние от твоего Господа и достаточный дар."},{"number":37,"arabic":"رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلرَّحْمَٰنِ ۖ لَا يَمْلِكُونَ مِنْهُ خِطَابًۭا","russian":"[Воздаяние и дар от] Господа небес и земли и всего, что между ними, Милостивого, с Которым [от страха] они не посмеют даже заговорить."},{"number":38,"arabic":"يَوْمَ يَقُومُ ٱلرُّوحُ وَٱلْمَلَٰٓئِكَةُ صَفًّۭا ۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنْ أَذِنَ لَهُ ٱلرَّحْمَٰنُ وَقَالَ صَوَابًۭا","russian":"В тот день Дух [Джибриль] и ангелы встанут рядами. Никто не промолвит ни слова, кроме тех, кому разрешит Милостивый. И говорить они будут правду."},{"number":39,"arabic":"ذَٰلِكَ ٱلْيَوْمُ ٱلْحَقُّ ۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا","russian":"Этот день – истина. И всякий, кто пожелает, может вернуться к своему Господу."},{"number":40,"arabic":"إِنَّآ أَنذَرْنَٰكُمْ عَذَابًۭا قَرِيبًۭا يَوْمَ يَنظُرُ ٱلْمَرْءُ مَا قَدَّمَتْ يَدَاهُ وَيَقُولُ ٱلْكَافِرُ يَٰلَيْتَنِى كُنتُ تُرَٰبًۢا","russian":"Поистине, Мы предостерегли вас от близкого наказания. В тот день человек посмотрит на то, что сделал своими руками [будь то хорошие или дурные поступки], и неверующий [увидев, что животные, приведенные на место сбора, будут обращены в прах] скажет: «О, если бы я стал землей [подобно им]!»"}]},{"number":79,"name":"Ан-Назиат","meaning":"Вырывающие","arabicName":"النَّازِعَاتِ","ayahs":[{"number":1,"arabic":"وَٱلنَّٰزِعَٰتِ غَرْقًۭا","russian":"Клянусь [ангелами] вырывающими [души неверующих] грубо,"},{"number":2,"arabic":"وَٱلنَّٰشِطَٰتِ نَشْطًۭا","russian":"[клянусь ангелами] извлекающими [души верующих] нежно,"},{"number":3,"arabic":"وَٱلسَّٰبِحَٰتِ سَبْحًۭا","russian":"[клянусь ангелами] плывущими плавно,"},{"number":4,"arabic":"فَٱلسَّٰبِقَٰتِ سَبْقًۭا","russian":"[клянусь ангелами] проносящимися стремительно"},{"number":5,"arabic":"فَٱلْمُدَبِّرَٰتِ أَمْرًۭا","russian":"и [клянусь ангелами] исполняющими поручения [Всевышнего]."},{"number":6,"arabic":"يَوْمَ تَرْجُفُ ٱلرَّاجِفَةُ","russian":"В тот день [когда наступит конец света] сотрясется сотрясающаяся [земля]."},{"number":7,"arabic":"تَتْبَعُهَا ٱلرَّادِفَةُ","russian":"Затем последует следующее [сотрясение]."},{"number":8,"arabic":"قُلُوبٌۭ يَوْمَئِذٍۢ وَاجِفَةٌ","russian":"Сердца в тот день будут трепетать."},{"number":9,"arabic":"أَبْصَٰرُهَا خَٰشِعَةٌۭ","russian":"Их взгляды станут смиренными [от увиденных ужасов]."},{"number":10,"arabic":"يَقُولُونَ أَءِنَّا لَمَرْدُودُونَ فِى ٱلْحَافِرَةِ","russian":"[Сейчас] Они [неверующие] говорят [не веря в воскрешение]: «Неужели [после смерти] мы вернемся в прежнее состояние [снова став живыми]?"},{"number":11,"arabic":"أَءِذَا كُنَّا عِظَٰمًۭا نَّخِرَةًۭ","russian":"Ведь мы будем истлевшими костями!»"},{"number":12,"arabic":"قَالُوا۟ تِلْكَ إِذًۭا كَرَّةٌ خَاسِرَةٌۭ","russian":"И они говорят: «Если так, то это будет проигрышное возвращение»."},{"number":13,"arabic":"فَإِنَّمَا هِىَ زَجْرَةٌۭ وَٰحِدَةٌۭ","russian":"Но лишь только раздастся один звук [второе дуновение в Рог],"},{"number":14,"arabic":"فَإِذَا هُم بِٱلسَّاهِرَةِ","russian":"как все они окажутся на поверхности [земли]."},{"number":15,"arabic":"هَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","russian":"Дошел ли до тебя рассказ о Мусе?"},{"number":16,"arabic":"إِذْ نَادَىٰهُ رَبُّهُۥ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًى","russian":"Вот воззвал его Господь к нему в священной долине Тува:"},{"number":17,"arabic":"ٱذْهَبْ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ","russian":"Ступай к Фараону, он преступил все границы [неверия и пороков]."},{"number":18,"arabic":"فَقُلْ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ","russian":"И скажи ему: «Нет ли у тебя желания очиститься?"},{"number":19,"arabic":"وَأَهْدِيَكَ إِلَىٰ رَبِّكَ فَتَخْشَىٰ","russian":"[Тогда] Я укажу тебе путь к твоему Господу, и ты станешь богобоязненным»."},{"number":20,"arabic":"فَأَرَىٰهُ ٱلْءَايَةَ ٱلْكُبْرَىٰ","russian":"И он показал ему великое знамение [чудо превращения посоха в змею]."},{"number":21,"arabic":"فَكَذَّبَ وَعَصَىٰ","russian":"Но [Фараон] не поверил ему и проявил непокорность."},{"number":22,"arabic":"ثُمَّ أَدْبَرَ يَسْعَىٰ","russian":"Затем он отвернулся и устремился прочь."},{"number":23,"arabic":"فَحَشَرَ فَنَادَىٰ","russian":"Он собрал [подданных] и воззвал [к ним]."},{"number":24,"arabic":"فَقَالَ أَنَا۠ رَبُّكُمُ ٱلْأَعْلَىٰ","russian":"И он сказал: «Я – ваш всевышний господь!»"},{"number":25,"arabic":"فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلْءَاخِرَةِ وَٱلْأُولَىٰٓ","russian":"И Аллах подверг его примерному наказанию как в следующей жизни, так и в земной [жизни, утопив в море]."},{"number":26,"arabic":"إِنَّ فِى ذَٰلِكَ لَعِبْرَةًۭ لِّمَن يَخْشَىٰٓ","russian":"Поистине, в этом – назидание для богобоязненных."},{"number":27,"arabic":"ءَأَنتُمْ أَشَدُّ خَلْقًا أَمِ ٱلسَّمَآءُ ۚ بَنَىٰهَا","russian":"Вас труднее создать или небо, которое [Аллах] воздвиг?"},{"number":28,"arabic":"رَفَعَ سَمْكَهَا فَسَوَّىٰهَا","russian":"Он поднял его своды и сделал совершенным."},{"number":29,"arabic":"وَأَغْطَشَ لَيْلَهَا وَأَخْرَجَ ضُحَىٰهَا","russian":"Он затемнил его ночью и вывел [светлый] день."},{"number":30,"arabic":"وَٱلْأَرْضَ بَعْدَ ذَٰلِكَ دَحَىٰهَآ","russian":"Землю Он после этого сделал ровной."},{"number":31,"arabic":"أَخْرَجَ مِنْهَا مَآءَهَا وَمَرْعَىٰهَا","russian":"[Аллах] Вывел из нее воду и пастбища."},{"number":32,"arabic":"وَٱلْجِبَالَ أَرْسَىٰهَا","russian":"И горы Он укрепил."},{"number":33,"arabic":"مَتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ","russian":"[Все это Он создал] На пользу вам и вашему скоту."},{"number":34,"arabic":"فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلْكُبْرَىٰ","russian":"И когда нагрянет Величайшая беда [Судный день],"},{"number":35,"arabic":"يَوْمَ يَتَذَكَّرُ ٱلْإِنسَٰنُ مَا سَعَىٰ","russian":"день, когда человек вспомнит все, ради чего он старался [в земной жизни]."},{"number":36,"arabic":"وَبُرِّزَتِ ٱلْجَحِيمُ لِمَن يَرَىٰ","russian":"И Ад предстанет перед теми, кто будет видеть."},{"number":37,"arabic":"فَأَمَّا مَن طَغَىٰ","russian":"Для того, кто перешел все границы"},{"number":38,"arabic":"وَءَاثَرَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","russian":"и предпочитал земную жизнь,"},{"number":39,"arabic":"فَإِنَّ ٱلْجَحِيمَ هِىَ ٱلْمَأْوَىٰ","russian":"поистине, пристанищем станет Ад."},{"number":40,"arabic":"وَأَمَّا مَنْ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفْسَ عَنِ ٱلْهَوَىٰ","russian":"А для того, кто боялся предстать перед своим Господом и удерживал себя от [запретных] желаний,"},{"number":41,"arabic":"فَإِنَّ ٱلْجَنَّةَ هِىَ ٱلْمَأْوَىٰ","russian":"пристанищем будет Рай."},{"number":42,"arabic":"يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا","russian":"У тебя [о Мухаммад] спрашивают о Часе [Судного дня]: когда он наступит?"},{"number":43,"arabic":"فِيمَ أَنتَ مِن ذِكْرَىٰهَآ","russian":"Откуда ты можешь знать об этом?"},{"number":44,"arabic":"إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ","russian":"Только у твоего Господа – конечное знание о нем."},{"number":45,"arabic":"إِنَّمَآ أَنتَ مُنذِرُ مَن يَخْشَىٰهَا","russian":"Поистине, ты – лишь увещеватель для тех, кто страшится его."},{"number":46,"arabic":"كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُوٓا۟ إِلَّا عَشِيَّةً أَوْ ضُحَىٰهَا","russian":"И в тот день, когда они увидят его, покажется, что они провели [в этом мире] лишь вечер или утро."}]},{"number":80,"name":"Абаса","meaning":"Нахмурился","arabicName":"عَبَسَ","ayahs":[{"number":1,"arabic":"عَبَسَ وَتَوَلَّىٰٓ","russian":"Он нахмурился и отвернулся"},{"number":2,"arabic":"أَن جَآءَهُ ٱلْأَعْمَىٰ","russian":"от того, что к нему пришел слепой."},{"number":3,"arabic":"وَمَا يُدْرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ","russian":"Откуда ты знаешь – возможно, он очистится"},{"number":4,"arabic":"أَوْ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكْرَىٰٓ","russian":"или примет наставление, и оно принесет ему пользу."},{"number":5,"arabic":"أَمَّا مَنِ ٱسْتَغْنَىٰ","russian":"Тому же, кто решил, что он ни в чем не нуждается,"},{"number":6,"arabic":"فَأَنتَ لَهُۥ تَصَدَّىٰ","russian":"ты уделяешь внимание."},{"number":7,"arabic":"وَمَا عَلَيْكَ أَلَّا يَزَّكَّىٰ","russian":"Но не будет твоей вины, если он не очистится."},{"number":8,"arabic":"وَأَمَّا مَن جَآءَكَ يَسْعَىٰ","russian":"А того, кто приходит к тебе, спеша"},{"number":9,"arabic":"وَهُوَ يَخْشَىٰ","russian":"и боясь [Аллаха],"},{"number":10,"arabic":"فَأَنتَ عَنْهُ تَلَهَّىٰ","russian":"ты оставляешь без внимания."},{"number":11,"arabic":"كَلَّآ إِنَّهَا تَذْكِرَةٌۭ","russian":"Но нет! Это – напоминание."},{"number":12,"arabic":"فَمَن شَآءَ ذَكَرَهُۥ","russian":"И кто пожелает, вспомнит [и примет] его."},{"number":13,"arabic":"فِى صُحُفٍۢ مُّكَرَّمَةٍۢ","russian":"Оно – в досточтимых свитках."},{"number":14,"arabic":"مَّرْفُوعَةٍۢ مُّطَهَّرَةٍۭ","russian":"[Эти свитки] Возвышены и чисты."},{"number":15,"arabic":"بِأَيْدِى سَفَرَةٍۢ","russian":"[Они] В руках [ангелов] посланцев"},{"number":16,"arabic":"كِرَامٍۭ بَرَرَةٍۢ","russian":"благородных и благочестивых."},{"number":17,"arabic":"قُتِلَ ٱلْإِنسَٰنُ مَآ أَكْفَرَهُۥ","russian":"Да погибнет [неверующий] человек! Как же он неблагодарен!"},{"number":18,"arabic":"مِنْ أَىِّ شَىْءٍ خَلَقَهُۥ","russian":"Из чего [Аллах] сотворил его?"},{"number":19,"arabic":"مِن نُّطْفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ","russian":"Он сотворил его из капли и предопределил."},{"number":20,"arabic":"ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ","russian":"Затем [Аллах] облегчил ему путь."},{"number":21,"arabic":"ثُمَّ أَمَاتَهُۥ فَأَقْبَرَهُۥ","russian":"Затем умертвил его и поместил в могилу."},{"number":22,"arabic":"ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ","russian":"Затем, когда пожелает [Аллах], воскресит его."},{"number":23,"arabic":"كَلَّا لَمَّا يَقْضِ مَآ أَمَرَهُۥ","russian":"Но нет! [Человек] Не выполняет того, что [Аллах] ему повелел."},{"number":24,"arabic":"فَلْيَنظُرِ ٱلْإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ","russian":"Пусть посмотрит человек на свою еду!"},{"number":25,"arabic":"أَنَّا صَبَبْنَا ٱلْمَآءَ صَبًّۭا","russian":"Мы проливаем обильные ливни."},{"number":26,"arabic":"ثُمَّ شَقَقْنَا ٱلْأَرْضَ شَقًّۭا","russian":"Затем рассекаем землю трещинами."},{"number":27,"arabic":"فَأَنۢبَتْنَا فِيهَا حَبًّۭا","russian":"И [Мы] взращиваем на ней семена."},{"number":28,"arabic":"وَعِنَبًۭا وَقَضْبًۭا","russian":"Виноград и люцерну."},{"number":29,"arabic":"وَزَيْتُونًۭا وَنَخْلًۭا","russian":"Оливы и пальмы."},{"number":30,"arabic":"وَحَدَآئِقَ غُلْبًۭا","russian":"Густые сады."},{"number":31,"arabic":"وَفَٰكِهَةًۭ وَأَبًّۭا","russian":"Фрукты и травы."},{"number":32,"arabic":"مَّتَٰعًۭا لَّكُمْ وَلِأَنْعَٰمِكُمْ","russian":"[Все это] На пользу вам и вашему скоту."},{"number":33,"arabic":"فَإِذَا جَآءَتِ ٱلصَّآخَّةُ","russian":"И когда раздастся оглушительный шум,"},{"number":34,"arabic":"يَوْمَ يَفِرُّ ٱلْمَرْءُ مِنْ أَخِيهِ","russian":"в этот день человек побежит от своего брата,"},{"number":35,"arabic":"وَأُمِّهِۦ وَأَبِيهِ","russian":"матери и отца,"},{"number":36,"arabic":"وَصَٰحِبَتِهِۦ وَبَنِيهِ","russian":"жены и детей."},{"number":37,"arabic":"لِكُلِّ ٱمْرِئٍۢ مِّنْهُمْ يَوْمَئِذٍۢ شَأْنٌۭ يُغْنِيهِ","russian":"В этот день каждый человек будет заботиться только о себе."},{"number":38,"arabic":"وُجُوهٌۭ يَوْمَئِذٍۢ مُّسْفِرَةٌۭ","russian":"В тот день [одни] лица будут сияющими,"},{"number":39,"arabic":"ضَاحِكَةٌۭ مُّسْتَبْشِرَةٌۭ","russian":"смеющимися и радостными."},{"number":40,"arabic":"وَوُجُوهٌۭ يَوْمَئِذٍ عَلَيْهَا غَبَرَةٌۭ","russian":"На [других же] лицах в этот день будет пыль,"},{"number":41,"arabic":"تَرْهَقُهَا قَتَرَةٌ","russian":"которая покроет их тьмой."},{"number":42,"arabic":"أُو۟لَٰٓئِكَ هُمُ ٱلْكَفَرَةُ ٱلْفَجَرَةُ","russian":"Это будут неверующие грешники."}]},{"number":81,"name":"Ат-Таквир","meaning":"Скручивание","arabicName":"التَّكۡوِيرِ","ayahs":[{"number":1,"arabic":"إِذَا ٱلشَّمْسُ كُوِّرَتْ","russian":"Когда солнце будет скручено."},{"number":2,"arabic":"وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتْ","russian":"И когда звезды упадут."},{"number":3,"arabic":"وَإِذَا ٱلْجِبَالُ سُيِّرَتْ","russian":"И когда горы сдвинутся."},{"number":4,"arabic":"وَإِذَا ٱلْعِشَارُ عُطِّلَتْ","russian":"И когда верблюдицы на десятом месяце беременности [которые считались у арабов самым ценным имуществом] пропадут."},{"number":5,"arabic":"وَإِذَا ٱلْوُحُوشُ حُشِرَتْ","russian":"И когда дикие животные будут собраны [на месте сбора для расчета между ними]."},{"number":6,"arabic":"وَإِذَا ٱلْبِحَارُ سُجِّرَتْ","russian":"И когда моря запылают."},{"number":7,"arabic":"وَإِذَا ٱلنُّفُوسُ زُوِّجَتْ","russian":"И когда души воссоединятся [со своими телами]."},{"number":8,"arabic":"وَإِذَا ٱلْمَوْءُۥدَةُ سُئِلَتْ","russian":"И когда погребенную заживо спросят,"},{"number":9,"arabic":"بِأَىِّ ذَنۢبٍۢ قُتِلَتْ","russian":"за какой грех ее убили."},{"number":10,"arabic":"وَإِذَا ٱلصُّحُفُ نُشِرَتْ","russian":"И когда свитки [с записями деяний] будут развернуты [для чтения]."},{"number":11,"arabic":"وَإِذَا ٱلسَّمَآءُ كُشِطَتْ","russian":"И когда небо будет сдернуто."},{"number":12,"arabic":"وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ","russian":"И когда Ад будет разожжен."},{"number":13,"arabic":"وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ","russian":"И когда Рай будет приближен [к богобоязненным верующим] –"},{"number":14,"arabic":"عَلِمَتْ نَفْسٌۭ مَّآ أَحْضَرَتْ","russian":"тогда узнает душа, с чем пришла."},{"number":15,"arabic":"فَلَآ أُقْسِمُ بِٱلْخُنَّسِ","russian":"И клянусь [небесными телами] появляющимися,"},{"number":16,"arabic":"ٱلْجَوَارِ ٱلْكُنَّسِ","russian":"движущимися и исчезающими!"},{"number":17,"arabic":"وَٱلَّيْلِ إِذَا عَسْعَسَ","russian":"И клянусь ночью наступающей!"},{"number":18,"arabic":"وَٱلصُّبْحِ إِذَا تَنَفَّسَ","russian":"И утром светлеющим!"},{"number":19,"arabic":"إِنَّهُۥ لَقَوْلُ رَسُولٍۢ كَرِيمٍۢ","russian":"[Клянусь в том, что] Это, поистине, – слова благородного посланника [Джибриля],"},{"number":20,"arabic":"ذِى قُوَّةٍ عِندَ ذِى ٱلْعَرْشِ مَكِينٍۢ","russian":"обладателя силы и высокого положения при Властелине Арша."},{"number":21,"arabic":"مُّطَاعٍۢ ثَمَّ أَمِينٍۢ","russian":"Ему там [на небесах] повинуются и доверяют."},{"number":22,"arabic":"وَمَا صَاحِبُكُم بِمَجْنُونٍۢ","russian":"[Также клянусь, что] Ваш знакомый [Мухаммад] не одержимый."},{"number":23,"arabic":"وَلَقَدْ رَءَاهُ بِٱلْأُفُقِ ٱلْمُبِينِ","russian":"И он видел его [Джибриля] на ясном горизонте."},{"number":24,"arabic":"وَمَا هُوَ عَلَى ٱلْغَيْبِ بِضَنِينٍۢ","russian":"И он не скупится передать скрытое."},{"number":25,"arabic":"وَمَا هُوَ بِقَوْلِ شَيْطَٰنٍۢ رَّجِيمٍۢ","russian":"И это – не речь проклятого шайтана."},{"number":26,"arabic":"فَأَيْنَ تَذْهَبُونَ","russian":"Куда же вы уходите?"},{"number":27,"arabic":"إِنْ هُوَ إِلَّا ذِكْرٌۭ لِّلْعَٰلَمِينَ","russian":"Это ни что иное, как напоминание [и наставление] для миров."},{"number":28,"arabic":"لِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ","russian":"Для тех из вас, кто желает следовать верным путем."},{"number":29,"arabic":"وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ","russian":"Но вы не пожелаете [этого], если не пожелает Аллах, Господь миров."}]},{"number":82,"name":"Аль-Инфитар","meaning":"Раскалывание","arabicName":"الانفِطَارِ","ayahs":[{"number":1,"arabic":"إِذَا ٱلسَّمَآءُ ٱنفَطَرَتْ","russian":"Когда небо разломится."},{"number":2,"arabic":"وَإِذَا ٱلْكَوَاكِبُ ٱنتَثَرَتْ","russian":"Когда звезды рассыплются."},{"number":3,"arabic":"وَإِذَا ٱلْبِحَارُ فُجِّرَتْ","russian":"И когда моря смешаются."},{"number":4,"arabic":"وَإِذَا ٱلْقُبُورُ بُعْثِرَتْ","russian":"И когда могилы перевернутся [и воскресшие рабы Аллаха покинут их] –"},{"number":5,"arabic":"عَلِمَتْ نَفْسٌۭ مَّا قَدَّمَتْ وَأَخَّرَتْ","russian":"каждый человек узнает, что он совершал [в земной жизни] и что оставил после себя [какова его участь в вечности]."},{"number":6,"arabic":"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلْكَرِيمِ","russian":"О человек! Что обмануло тебя относительно твоего Щедрого Господа?"},{"number":7,"arabic":"ٱلَّذِى خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ","russian":"[Ведь Аллах – Тот] Кто сотворил тебя и придал тебе совершенное и соразмерное строение?"},{"number":8,"arabic":"فِىٓ أَىِّ صُورَةٍۢ مَّا شَآءَ رَكَّبَكَ","russian":"Он придал тебе образ, какой пожелал."},{"number":9,"arabic":"كَلَّا بَلْ تُكَذِّبُونَ بِٱلدِّينِ","russian":"Но нет! Вы все равно не верите в воздаяние!"},{"number":10,"arabic":"وَإِنَّ عَلَيْكُمْ لَحَٰفِظِينَ","russian":"И, поистине, у вас есть наблюдатели –"},{"number":11,"arabic":"كِرَامًۭا كَٰتِبِينَ","russian":"благородные писцы."},{"number":12,"arabic":"يَعْلَمُونَ مَا تَفْعَلُونَ","russian":"Они знают обо всем, что вы делаете."},{"number":13,"arabic":"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍۢ","russian":"Поистине, праведники – в блаженстве."},{"number":14,"arabic":"وَإِنَّ ٱلْفُجَّارَ لَفِى جَحِيمٍۢ","russian":"И, поистине, [неверующие] грешники – в Аду."},{"number":15,"arabic":"يَصْلَوْنَهَا يَوْمَ ٱلدِّينِ","russian":"Они войдут туда в День воздаяния."},{"number":16,"arabic":"وَمَا هُمْ عَنْهَا بِغَآئِبِينَ","russian":"И они не выйдут оттуда."},{"number":17,"arabic":"وَمَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","russian":"Откуда ты мог знать, что такое День воздаяния?"},{"number":18,"arabic":"ثُمَّ مَآ أَدْرَىٰكَ مَا يَوْمُ ٱلدِّينِ","russian":"Действительно, откуда ты мог знать, что такое День воздаяния?"},{"number":19,"arabic":"يَوْمَ لَا تَمْلِكُ نَفْسٌۭ لِّنَفْسٍۢ شَيْـًۭٔا ۖ وَٱلْأَمْرُ يَوْمَئِذٍۢ لِّلَّهِ","russian":"В тот день ни один человек ничем не поможет другому. И вся власть в тот день будет у Аллаха."}]},{"number":83,"name":"Аль-Мутаффифин","meaning":"Обвешивающие","arabicName":"المُطَفِّفِينَ","ayahs":[{"number":1,"arabic":"وَيْلٌۭ لِّلْمُطَفِّفِينَ","russian":"Горе обвешивающим."},{"number":2,"arabic":"ٱلَّذِينَ إِذَا ٱكْتَالُوا۟ عَلَى ٱلنَّاسِ يَسْتَوْفُونَ","russian":"Тем, кто, покупая у других, требует сполна,"},{"number":3,"arabic":"وَإِذَا كَالُوهُمْ أَو وَّزَنُوهُمْ يُخْسِرُونَ","russian":"а когда [они] отмеряют или взвешивают для других, то наносят им убыток."},{"number":4,"arabic":"أَلَا يَظُنُّ أُو۟لَٰٓئِكَ أَنَّهُم مَّبْعُوثُونَ","russian":"Разве не думают они, что будут воскрешены"},{"number":5,"arabic":"لِيَوْمٍ عَظِيمٍۢ","russian":"для Великого дня [и придется отчитываться за все дела]?!"},{"number":6,"arabic":"يَوْمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلْعَٰلَمِينَ","russian":"Дня, когда люди предстанут перед Господом миров."},{"number":7,"arabic":"كَلَّآ إِنَّ كِتَٰبَ ٱلْفُجَّارِ لَفِى سِجِّينٍۢ","russian":"Нет же! Книга нечестивцев окажется в Сиджине."},{"number":8,"arabic":"وَمَآ أَدْرَىٰكَ مَا سِجِّينٌۭ","russian":"Откуда ты мог знать, что такое Сиджин?"},{"number":9,"arabic":"كِتَٰبٌۭ مَّرْقُومٌۭ","russian":"[Это –] Запечатанная книга."},{"number":10,"arabic":"وَيْلٌۭ يَوْمَئِذٍۢ لِّلْمُكَذِّبِينَ","russian":"Горе в тот день отрицающим,"},{"number":11,"arabic":"ٱلَّذِينَ يُكَذِّبُونَ بِيَوْمِ ٱلدِّينِ","russian":"которые отрицали Судный день!"},{"number":12,"arabic":"وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعْتَدٍ أَثِيمٍ","russian":"А считает его ложью только преступник [и] грешник."},{"number":13,"arabic":"إِذَا تُتْلَىٰ عَلَيْهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلْأَوَّلِينَ","russian":"Когда ему читают Наши аяты, он говорит: «Это – сказки древних народов!»"},{"number":14,"arabic":"كَلَّا ۖ بَلْ ۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ يَكْسِبُونَ","russian":"Нет же! Окутало их сердца то, что они совершали [из грехов]."},{"number":15,"arabic":"كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ","russian":"Нет же! В тот день они будут отделены от своего Господа завесой."},{"number":16,"arabic":"ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ","russian":"Затем они попадут в Ад."},{"number":17,"arabic":"ثُمَّ يُقَالُ هَٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ","russian":"Затем им скажут: «Вот то [наказание в Аду], которое вы отрицали!»"},{"number":18,"arabic":"كَلَّآ إِنَّ كِتَٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ","russian":"Но нет! Книга праведников окажется в Иллиййуне."},{"number":19,"arabic":"وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ","russian":"Откуда ты мог знать, что такое Иллиййун?"},{"number":20,"arabic":"كِتَٰبٌۭ مَّرْقُومٌۭ","russian":"[Это –] Запечатанная книга."},{"number":21,"arabic":"يَشْهَدُهُ ٱلْمُقَرَّبُونَ","russian":"Там находятся приближенные [ангелы]."},{"number":22,"arabic":"إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ","russian":"Поистине, праведники – в блаженстве."},{"number":23,"arabic":"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","russian":"Они будут на ложах созерцать [красоты Рая]."},{"number":24,"arabic":"تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ","russian":"Ты увидишь на их лицах блеск блаженства."},{"number":25,"arabic":"يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ","russian":"Их будут поить запечатанным [райским] вином."},{"number":26,"arabic":"خِتَٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَٰفِسُونَ","russian":"Запечатано оно миском. Пусть же к этому стремятся стремящиеся!"},{"number":27,"arabic":"وَمِزَاجُهُۥ مِن تَسْنِيمٍ","russian":"Оно смешано с Таснимом,"},{"number":28,"arabic":"عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ","russian":"[напитком] из источника, из которого пьют приближенные."},{"number":29,"arabic":"إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ","russian":"Поистине, [неверующие] преступники [в земной жизни] смеялись над верующими."},{"number":30,"arabic":"وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ","russian":"И когда [верующие] проходили мимо них, они перемигивались."},{"number":31,"arabic":"وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ","russian":"А когда возвращались к своим семьям, веселились."},{"number":32,"arabic":"وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ","russian":"И когда видели их, говорили: «Поистине, вот эти сбились с [истинного] пути»."},{"number":33,"arabic":"وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَٰفِظِينَ","russian":"Но они [неверующие] не были посланы к ним стражами."},{"number":34,"arabic":"فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ","russian":"Но в этот [Судный] день верующие будут смеяться над неверующими,"},{"number":35,"arabic":"عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ","russian":"наблюдая [за ними] на ложах."},{"number":36,"arabic":"هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ","russian":"Получают ли неверующие [справедливое] воздаяние за то, что они делали [в земной жизни]?"}]},{"number":84,"name":"Аль-Иншикак","meaning":"Разверзнется","arabicName":"الانشِقَاقِ","ayahs":[{"number":1,"arabic":"إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ","russian":"Когда небо расколется,"},{"number":2,"arabic":"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","russian":"внемля своему Господу, как и должно."},{"number":3,"arabic":"وَإِذَا ٱلْأَرْضُ مُدَّتْ","russian":"И когда земля вытянется [став гладкой]."},{"number":4,"arabic":"وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ","russian":"И извергнет все, что внутри ее, и опустошится,"},{"number":5,"arabic":"وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ","russian":"внемля своему Господу, как и положено."},{"number":6,"arabic":"يَٰٓأَيُّهَا ٱلْإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَٰقِيهِ","russian":"О человек! Ты стараешься [и итог твоих стараний] – у твоего Господа. Ты встретишься с Ним."},{"number":7,"arabic":"فَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ بِيَمِينِهِۦ","russian":"А для того, кому его книга будет вручена в правую руку,"},{"number":8,"arabic":"فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا","russian":"отчет будет легким."},{"number":9,"arabic":"وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا","russian":"И он вернется к своей семье радостным."},{"number":10,"arabic":"وَأَمَّا مَنْ أُوتِىَ كِتَٰبَهُۥ وَرَآءَ ظَهْرِهِۦ","russian":"А тот, кому книга [его деяний] будет подана из-за спины,"},{"number":11,"arabic":"فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا","russian":"призовет смерть."},{"number":12,"arabic":"وَيَصْلَىٰ سَعِيرًا","russian":"И он попадет в Ад."},{"number":13,"arabic":"إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا","russian":"В кругу семьи он радовался."},{"number":14,"arabic":"إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ","russian":"Он думал, что не вернется [обратно, воскреснув из мертвых]."},{"number":15,"arabic":"بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا","russian":"Но нет! Поистине, его Господь видел его [и все его поступки]."},{"number":16,"arabic":"فَلَآ أُقْسِمُ بِٱلشَّفَقِ","russian":"Клянусь вечерней зарей!"},{"number":17,"arabic":"وَٱلَّيْلِ وَمَا وَسَقَ","russian":"И клянусь ночью и тем [миром], что она покрывает!"},{"number":18,"arabic":"وَٱلْقَمَرِ إِذَا ٱتَّسَقَ","russian":"И полной луною! –"},{"number":19,"arabic":"لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ","russian":"Вы будете переходить из одного состояния в другое [сначала из жизни в смерть, потом наступят испытания в могиле, потом воскрешение, Судный день и его тяготы]."},{"number":20,"arabic":"فَمَا لَهُمْ لَا يُؤْمِنُونَ","russian":"Что же с ними? Почему же они не верят?"},{"number":21,"arabic":"وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩","russian":"Почему не совершают земной поклон, когда им читают Куръан?"},{"number":22,"arabic":"بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ","russian":"Но неверующие считают [все] это ложью."},{"number":23,"arabic":"وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ","russian":"И Аллах лучше знает, что у них внутри."},{"number":24,"arabic":"فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ","russian":"Обрадуй же их болезненным наказанием."},{"number":25,"arabic":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ","russian":"[Всех людей] Кроме тех, кто уверовал и совершал праведные поступки. Им – нескончаемая награда."}]},{"number":85,"name":"Аль-Бурудж","meaning":"Созвездия","arabicName":"البُرُوجِ","ayahs":[{"number":1,"arabic":"وَٱلسَّمَآءِ ذَاتِ ٱلْبُرُوجِ","russian":"Клянусь небом с созвездиями!"},{"number":2,"arabic":"وَٱلْيَوْمِ ٱلْمَوْعُودِ","russian":"И клянусь обещанным днем!"},{"number":3,"arabic":"وَشَاهِدٍۢ وَمَشْهُودٍۢ","russian":"И клянусь свидетельствующим и засвидетельствованным!"},{"number":4,"arabic":"قُتِلَ أَصْحَٰبُ ٱلْأُخْدُودِ","russian":"Прокляты хозяева рва!"},{"number":5,"arabic":"ٱلنَّارِ ذَاتِ ٱلْوَقُودِ","russian":"[Хозяева] Огня пылающего."},{"number":6,"arabic":"إِذْ هُمْ عَلَيْهَا قُعُودٌۭ","russian":"И они сидели возле него,"},{"number":7,"arabic":"وَهُمْ عَلَىٰ مَا يَفْعَلُونَ بِٱلْمُؤْمِنِينَ شُهُودٌۭ","russian":"Наблюдая за тем, как поступают с верующими."},{"number":8,"arabic":"وَمَا نَقَمُوا۟ مِنْهُمْ إِلَّآ أَن يُؤْمِنُوا۟ بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَمِيدِ","russian":"И они мстили им только за то, что те уверовали в Аллаха Достойного, Хвалимого."},{"number":9,"arabic":"ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ۚ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ","russian":"Ему принадлежит власть над небесами и землей. И Аллах – Свидетель всему!"},{"number":10,"arabic":"إِنَّ ٱلَّذِينَ فَتَنُوا۟ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ ثُمَّ لَمْ يَتُوبُوا۟ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ ٱلْحَرِيقِ","russian":"Поистине, кто подвергал мучениям верующих мужчин и женщин и не покаялся, тем [уготованы] адские муки, муки обжигающего огня."},{"number":11,"arabic":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ جَنَّٰتٌۭ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ۚ ذَٰلِكَ ٱلْفَوْزُ ٱلْكَبِيرُ","russian":"Поистине, кто уверовал и совершал благие поступки, тем – [райские] сады, под которыми текут реки. Это – великий успех!"},{"number":12,"arabic":"إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ","russian":"Поистине, кара твоего Господа страшна!"},{"number":13,"arabic":"إِنَّهُۥ هُوَ يُبْدِئُ وَيُعِيدُ","russian":"Поистине, Он творит и возвращает."},{"number":14,"arabic":"وَهُوَ ٱلْغَفُورُ ٱلْوَدُودُ","russian":"Он – Прощающий, Любящий."},{"number":15,"arabic":"ذُو ٱلْعَرْشِ ٱلْمَجِيدُ","russian":"Владыка Арша [Трона], Славный."},{"number":16,"arabic":"فَعَّالٌۭ لِّمَا يُرِيدُ","russian":"Он совершает все, что пожелает."},{"number":17,"arabic":"هَلْ أَتَىٰكَ حَدِيثُ ٱلْجُنُودِ","russian":"Дошел ли до тебя рассказ о войске"},{"number":18,"arabic":"فِرْعَوْنَ وَثَمُودَ","russian":"Фараона и самудянах?"},{"number":19,"arabic":"بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى تَكْذِيبٍۢ","russian":"Но неверующие считают это ложью."},{"number":20,"arabic":"وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطٌۢ","russian":"Аллах же [Своим Знанием и Могуществом] охватывает их."},{"number":21,"arabic":"بَلْ هُوَ قُرْءَانٌۭ مَّجِيدٌۭ","russian":"Это – славный Куръан"},{"number":22,"arabic":"فِى لَوْحٍۢ مَّحْفُوظٍۭ","russian":"в Хранимой книге."}]},{"number":86,"name":"Ат-Тарик","meaning":"Ночной путник","arabicName":"الطَّارِقِ","ayahs":[{"number":1,"arabic":"وَٱلسَّمَآءِ وَٱلطَّارِقِ","russian":"Клянусь небом и Появляющимся ночью!"},{"number":2,"arabic":"وَمَآ أَدْرَىٰكَ مَا ٱلطَّارِقُ","russian":"Откуда ты мог знать, что такое Появляющийся ночью?"},{"number":3,"arabic":"ٱلنَّجْمُ ٱلثَّاقِبُ","russian":"Это – звезда, пронзающая [тьму своим светом]."},{"number":4,"arabic":"إِن كُلُّ نَفْسٍۢ لَّمَّا عَلَيْهَا حَافِظٌۭ","russian":"Нет души, у которой не было бы хранителя."},{"number":5,"arabic":"فَلْيَنظُرِ ٱلْإِنسَٰنُ مِمَّ خُلِقَ","russian":"Так пусть человек посмотрит, из чего он сотворен."},{"number":6,"arabic":"خُلِقَ مِن مَّآءٍۢ دَافِقٍۢ","russian":"Он сотворен из излившейся жидкости,"},{"number":7,"arabic":"يَخْرُجُ مِنۢ بَيْنِ ٱلصُّلْبِ وَٱلتَّرَآئِبِ","russian":"которая выходит из позвоночника и грудных костей."},{"number":8,"arabic":"إِنَّهُۥ عَلَىٰ رَجْعِهِۦ لَقَادِرٌۭ","russian":"Поистине, Он [Всевышний Аллах] способен [воскресив] вернуть его [к жизни]."},{"number":9,"arabic":"يَوْمَ تُبْلَى ٱلسَّرَآئِرُ","russian":"В тот день будут раскрыты все тайны."},{"number":10,"arabic":"فَمَا لَهُۥ مِن قُوَّةٍۢ وَلَا نَاصِرٍۢ","russian":"И тогда не будет у него [человека] ни силы, ни помощника."},{"number":11,"arabic":"وَٱلسَّمَآءِ ذَاتِ ٱلرَّجْعِ","russian":"Клянусь небом, изливающим дожди!"},{"number":12,"arabic":"وَٱلْأَرْضِ ذَاتِ ٱلصَّدْعِ","russian":"Клянусь землей, которая раскалывается!"},{"number":13,"arabic":"إِنَّهُۥ لَقَوْلٌۭ فَصْلٌۭ","russian":"Это [Куръан], поистине, – Слово различающее [где истина, а где ложь]."},{"number":14,"arabic":"وَمَا هُوَ بِٱلْهَزْلِ","russian":"И это не шутка."},{"number":15,"arabic":"إِنَّهُمْ يَكِيدُونَ كَيْدًۭا","russian":"Поистине, они [неверующие] строят козни."},{"number":16,"arabic":"وَأَكِيدُ كَيْدًۭا","russian":"И Я воздам им за [эти их] козни."},{"number":17,"arabic":"فَمَهِّلِ ٱلْكَٰفِرِينَ أَمْهِلْهُمْ رُوَيْدًۢا","russian":"Так дай же неверующим отсрочку! Подожди немного [и Аллах Сам воздаст им по справедливости]!"}]},{"number":87,"name":"Аль-Аля","meaning":"Высочайший","arabicName":"الأَعۡلَىٰ","ayahs":[{"number":1,"arabic":"سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى","russian":"Возвеличивай имя Господа твоего Всевышнего!"},{"number":2,"arabic":"ٱلَّذِى خَلَقَ فَسَوَّىٰ","russian":"[Он – Тот] Кто сотворил [все сущее] и соразмерил,"},{"number":3,"arabic":"وَٱلَّذِى قَدَّرَ فَهَدَىٰ","russian":"Который предопределил и указал путь,"},{"number":4,"arabic":"وَٱلَّذِىٓ أَخْرَجَ ٱلْمَرْعَىٰ","russian":"Который взрастил пастбища."},{"number":5,"arabic":"فَجَعَلَهُۥ غُثَآءً أَحْوَىٰ","russian":"И превратил их в черный сор."},{"number":6,"arabic":"سَنُقْرِئُكَ فَلَا تَنسَىٰٓ","russian":"Мы дадим тебе прочесть Его [Куръан], и ты не забудешь [ничего из него],"},{"number":7,"arabic":"إِلَّا مَا شَآءَ ٱللَّهُ ۚ إِنَّهُۥ يَعْلَمُ ٱلْجَهْرَ وَمَا يَخْفَىٰ","russian":"кроме того, что пожелает Аллах. Поистине, Он знает явное и скрытое."},{"number":8,"arabic":"وَنُيَسِّرُكَ لِلْيُسْرَىٰ","russian":"И Мы облегчим тебе путь к легкому."},{"number":9,"arabic":"فَذَكِّرْ إِن نَّفَعَتِ ٱلذِّكْرَىٰ","russian":"Наставляй же [людей], если напоминание полезно."},{"number":10,"arabic":"سَيَذَّكَّرُ مَن يَخْشَىٰ","russian":"Примет [наставление] тот, кто страшится [Аллаха]."},{"number":11,"arabic":"وَيَتَجَنَّبُهَا ٱلْأَشْقَى","russian":"И отвернется от него несчастнейший,"},{"number":12,"arabic":"ٱلَّذِى يَصْلَى ٱلنَّارَ ٱلْكُبْرَىٰ","russian":"который войдет в великий огонь."},{"number":13,"arabic":"ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ","russian":"Затем он не сможет ни умереть там, ни жить."},{"number":14,"arabic":"قَدْ أَفْلَحَ مَن تَزَكَّىٰ","russian":"Преуспеет тот, кто очистился [от неверия и грехов],"},{"number":15,"arabic":"وَذَكَرَ ٱسْمَ رَبِّهِۦ فَصَلَّىٰ","russian":"поминал имя своего Господа и совершал намаз."},{"number":16,"arabic":"بَلْ تُؤْثِرُونَ ٱلْحَيَوٰةَ ٱلدُّنْيَا","russian":"Но вы предпочитаете земную жизнь."},{"number":17,"arabic":"وَٱلْءَاخِرَةُ خَيْرٌۭ وَأَبْقَىٰٓ","russian":"А вечная жизнь – лучше и не будет иметь конца."},{"number":18,"arabic":"إِنَّ هَٰذَا لَفِى ٱلصُّحُفِ ٱلْأُولَىٰ","russian":"Поистине, об этом [говорится] в первых свитках –"},{"number":19,"arabic":"صُحُفِ إِبْرَٰهِيمَ وَمُوسَىٰ","russian":"свитках Ибрахима и Мусы."}]},{"number":88,"name":"Аль-Гашия","meaning":"Покрывающее","arabicName":"الغَاشِيَةِ","ayahs":[{"number":1,"arabic":"هَلْ أَتَىٰكَ حَدِيثُ ٱلْغَٰشِيَةِ","russian":"Дошел ли до тебя рассказ об Покрывающем?"},{"number":2,"arabic":"وُجُوهٌۭ يَوْمَئِذٍ خَٰشِعَةٌ","russian":"[Некоторые] Лица в тот день будут унижены,"},{"number":3,"arabic":"عَامِلَةٌۭ نَّاصِبَةٌۭ","russian":"измучены трудом, утомлены [и это лица неверующих]."},{"number":4,"arabic":"تَصْلَىٰ نَارًا حَامِيَةًۭ","russian":"Они попадут в Огонь обжигающий."},{"number":5,"arabic":"تُسْقَىٰ مِنْ عَيْنٍ ءَانِيَةٍۢ","russian":"Их будут поить из источника кипящего."},{"number":6,"arabic":"لَّيْسَ لَهُمْ طَعَامٌ إِلَّا مِن ضَرِيعٍۢ","russian":"Не будет у них еды, кроме колючек."},{"number":7,"arabic":"لَّا يُسْمِنُ وَلَا يُغْنِى مِن جُوعٍۢ","russian":"[Эта еда] Не прибавит им веса и не утолит голод."},{"number":8,"arabic":"وُجُوهٌۭ يَوْمَئِذٍۢ نَّاعِمَةٌۭ","russian":"[Другие же] Лица [верующих] в тот день будут радостны."},{"number":9,"arabic":"لِّسَعْيِهَا رَاضِيَةٌۭ","russian":"Они будут довольны своими стараниями [в земной жизни]."},{"number":10,"arabic":"فِى جَنَّةٍ عَالِيَةٍۢ","russian":"[Они пребудут] В высоком [райском] саду."},{"number":11,"arabic":"لَّا تَسْمَعُ فِيهَا لَٰغِيَةًۭ","russian":"Они не услышат там пустословия."},{"number":12,"arabic":"فِيهَا عَيْنٌۭ جَارِيَةٌۭ","russian":"Там – источник текущий."},{"number":13,"arabic":"فِيهَا سُرُرٌۭ مَّرْفُوعَةٌۭ","russian":"Там ложа поднятые."},{"number":14,"arabic":"وَأَكْوَابٌۭ مَّوْضُوعَةٌۭ","russian":"И чаши расставлены [вокруг райского источника]."},{"number":15,"arabic":"وَنَمَارِقُ مَصْفُوفَةٌۭ","russian":"[Там –] Подушки разложены."},{"number":16,"arabic":"وَزَرَابِىُّ مَبْثُوثَةٌ","russian":"И ковры расстелены."},{"number":17,"arabic":"أَفَلَا يَنظُرُونَ إِلَى ٱلْإِبِلِ كَيْفَ خُلِقَتْ","russian":"Разве они не смотрят на верблюда – [на то] как он создан."},{"number":18,"arabic":"وَإِلَى ٱلسَّمَآءِ كَيْفَ رُفِعَتْ","russian":"И на небо – как оно поднято."},{"number":19,"arabic":"وَإِلَى ٱلْجِبَالِ كَيْفَ نُصِبَتْ","russian":"И на горы – как они установлены."},{"number":20,"arabic":"وَإِلَى ٱلْأَرْضِ كَيْفَ سُطِحَتْ","russian":"И на землю – как она расстелена."},{"number":21,"arabic":"فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌۭ","russian":"Так напоминай [и наставляй, о Мухаммад], ведь ты – напоминающий [пророк]."},{"number":22,"arabic":"لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ","russian":"И ты не властен над ними."},{"number":23,"arabic":"إِلَّا مَن تَوَلَّىٰ وَكَفَرَ","russian":"А тех, кто отвернется [от истины] и не поверит,"},{"number":24,"arabic":"فَيُعَذِّبُهُ ٱللَّهُ ٱلْعَذَابَ ٱلْأَكْبَرَ","russian":"Аллах подвергнет великому наказанию."},{"number":25,"arabic":"إِنَّ إِلَيْنَآ إِيَابَهُمْ","russian":"Поистине, к Нам – их возвращение."},{"number":26,"arabic":"ثُمَّ إِنَّ عَلَيْنَا حِسَابَهُم","russian":"А затем мы спросим с них [и воздадим за их поступки]."}]},{"number":89,"name":"Аль-Фаджр","meaning":"Рассвет","arabicName":"الفَجۡرِ","ayahs":[{"number":1,"arabic":"وَٱلْفَجْرِ","russian":"Клянусь рассветом!"},{"number":2,"arabic":"وَلَيَالٍ عَشْرٍۢ","russian":"И клянусь десятью ночами!"},{"number":3,"arabic":"وَٱلشَّفْعِ وَٱلْوَتْرِ","russian":"И клянусь четным и нечетным!"},{"number":4,"arabic":"وَٱلَّيْلِ إِذَا يَسْرِ","russian":"И клянусь ночью, когда она уходит!"},{"number":5,"arabic":"هَلْ فِى ذَٰلِكَ قَسَمٌۭ لِّذِى حِجْرٍ","russian":"Есть ли среди этих [клятв] клятва [достаточная] для обладателя разума?"},{"number":6,"arabic":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ","russian":"Разве ты не видел, что твой Господь сделал с адитами,"},{"number":7,"arabic":"إِرَمَ ذَاتِ ٱلْعِمَادِ","russian":"[народом] Ирама, у которого были [дома с] колоннами?!"},{"number":8,"arabic":"ٱلَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى ٱلْبِلَٰدِ","russian":"Подобных им не было создано на земле!"},{"number":9,"arabic":"وَثَمُودَ ٱلَّذِينَ جَابُوا۟ ٱلصَّخْرَ بِٱلْوَادِ","russian":"[И разве ты не знаешь, что Аллах сделал] С самудянами, которые пробивали скалы в долине [и строили свои дома]?"},{"number":10,"arabic":"وَفِرْعَوْنَ ذِى ٱلْأَوْتَادِ","russian":"[И разве ты не знаешь, как Аллах поступил] С Фараоном, обладателем кольев?"},{"number":11,"arabic":"ٱلَّذِينَ طَغَوْا۟ فِى ٱلْبِلَٰدِ","russian":"Они преступали границы [дозволенного] на земле"},{"number":12,"arabic":"فَأَكْثَرُوا۟ فِيهَا ٱلْفَسَادَ","russian":"и приумножали на ней порок."},{"number":13,"arabic":"فَصَبَّ عَلَيْهِمْ رَبُّكَ سَوْطَ عَذَابٍ","russian":"И обрушил твой Господь на них бич наказания."},{"number":14,"arabic":"إِنَّ رَبَّكَ لَبِٱلْمِرْصَادِ","russian":"Поистине, твой Господь все видит."},{"number":15,"arabic":"فَأَمَّا ٱلْإِنسَٰنُ إِذَا مَا ٱبْتَلَىٰهُ رَبُّهُۥ فَأَكْرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّىٓ أَكْرَمَنِ","russian":"Когда Господь испытывает человека, проявляя к нему щедрость и наделяя его благами, тот говорит: «Мой Господь проявил ко мне щедрость»."},{"number":16,"arabic":"وَأَمَّآ إِذَا مَا ٱبْتَلَىٰهُ فَقَدَرَ عَلَيْهِ رِزْقَهُۥ فَيَقُولُ رَبِّىٓ أَهَٰنَنِ","russian":"А когда Он испытывает его, ограничивая его удел, тот говорит: «Мой Господь унизил меня!»"},{"number":17,"arabic":"كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ","russian":"Но нет! Вы сами не проявляете щедрость к сиротам."},{"number":18,"arabic":"وَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","russian":"И не побуждаете друг друга кормить нищего."},{"number":19,"arabic":"وَتَأْكُلُونَ ٱلتُّرَاثَ أَكْلًۭا لَّمًّۭا","russian":"И проедаете наследство целиком [не разбирая, где ваша доля, а где чужая]."},{"number":20,"arabic":"وَتُحِبُّونَ ٱلْمَالَ حُبًّۭا جَمًّۭا","russian":"И любите богатство страстно."},{"number":21,"arabic":"كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّۭا دَكًّۭا","russian":"Но нет! Когда земля рассыплется на кусочки [и превратится в пыль],"},{"number":22,"arabic":"وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّۭا صَفًّۭا","russian":"и придет повеление твоего Господа, и ангелы – рядами,"},{"number":23,"arabic":"وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍۢ يَتَذَكَّرُ ٱلْإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ","russian":"и приведут в тот день Ад, – тогда только [неверующий] человек осознает [истину]. Но зачем ему [это] осознание? [Уже будет поздно!]"},{"number":24,"arabic":"يَقُولُ يَٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى","russian":"Он [неверующий] скажет [с сожалением]: «Если бы я заранее подготовился к своей [вечной] жизни…»"},{"number":25,"arabic":"فَيَوْمَئِذٍۢ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌۭ","russian":"В тот день никто не накажет так, как наказывает Он [Аллах],"},{"number":26,"arabic":"وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌۭ","russian":"и никто не наложит оковы, какие накладывает Он."},{"number":27,"arabic":"يَٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ","russian":"[Праведному верующему скажут:] О душа, обретшая покой!"},{"number":28,"arabic":"ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةًۭ مَّرْضِيَّةًۭ","russian":"Вернись к своему Господу довольной и нашедшей довольство [Аллаха]!"},{"number":29,"arabic":"فَٱدْخُلِى فِى عِبَٰدِى","russian":"Войди в число Моих [праведных] рабов!"},{"number":30,"arabic":"وَٱدْخُلِى جَنَّتِى","russian":"И войди в Мой Рай!"}]},{"number":90,"name":"Аль-Балад","meaning":"Город","arabicName":"البَلَدِ","ayahs":[{"number":1,"arabic":"لَآ أُقْسِمُ بِهَٰذَا ٱلْبَلَدِ","russian":"Клянусь этим городом [Меккой]!"},{"number":2,"arabic":"وَأَنتَ حِلٌّۢ بِهَٰذَا ٱلْبَلَدِ","russian":"И ты [о Мухаммад] живешь в этом городе."},{"number":3,"arabic":"وَوَالِدٍۢ وَمَا وَلَدَ","russian":"Клянусь родителем [Адамом] и теми, кого он родил [его потомками]!"},{"number":4,"arabic":"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِى كَبَدٍ","russian":"Поистине, Мы создали человека [чтобы он жил] в трудностях [так, что он от рождения и до смерти испытывает различные тяготы]."},{"number":5,"arabic":"أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌۭ","russian":"Неужели он [неверующий] считает, что никто не справится с ним?"},{"number":6,"arabic":"يَقُولُ أَهْلَكْتُ مَالًۭا لُّبَدًا","russian":"Он говорит: «Я потратил богатство огромное [на борьбу с Исламом]!»"},{"number":7,"arabic":"أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ","russian":"Неужели он считает, что его никто не видел?!"},{"number":8,"arabic":"أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ","russian":"Разве Мы не наделили его парой глаз,"},{"number":9,"arabic":"وَلِسَانًۭا وَشَفَتَيْنِ","russian":"языком и парой губ?"},{"number":10,"arabic":"وَهَدَيْنَٰهُ ٱلنَّجْدَيْنِ","russian":"Разве Мы не указали ему [верный путь] из двух путей?"},{"number":11,"arabic":"فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ","russian":"Он не стал преодолевать трудность [совершая хорошие поступки]."},{"number":12,"arabic":"وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ","russian":"Откуда ты мог знать, что такое «аль-Оакаба» [трудность, крутой подъем]?"},{"number":13,"arabic":"فَكُّ رَقَبَةٍ","russian":"[Это] Освобождение раба"},{"number":14,"arabic":"أَوْ إِطْعَٰمٌۭ فِى يَوْمٍۢ ذِى مَسْغَبَةٍۢ","russian":"или кормление [бедняка] в трудный [голодный] день,"},{"number":15,"arabic":"يَتِيمًۭا ذَا مَقْرَبَةٍ","russian":"[кормление] сироты из родственников"},{"number":16,"arabic":"أَوْ مِسْكِينًۭا ذَا مَتْرَبَةٍۢ","russian":"или попавшего в беду нищего."},{"number":17,"arabic":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ","russian":"Затем [следует] быть из тех, кто уверовал, и заповедал другим терпение, и заповедал другим милосердие."},{"number":18,"arabic":"أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْمَيْمَنَةِ","russian":"Таковы люди правой стороны."},{"number":19,"arabic":"وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِنَا هُمْ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ","russian":"Те же, кто не поверил в Наши знамения [аяты Куръана], они – люди левой стороны."},{"number":20,"arabic":"عَلَيْهِمْ نَارٌۭ مُّؤْصَدَةٌۢ","russian":"Над ними сомкнется огненный свод."}]},{"number":91,"name":"Аш-Шамс","meaning":"Солнце","arabicName":"الشَّمۡسِ","ayahs":[{"number":1,"arabic":"وَٱلشَّمْسِ وَضُحَىٰهَا","russian":"Клянусь солнцем и его [ярким] светом!"},{"number":2,"arabic":"وَٱلْقَمَرِ إِذَا تَلَىٰهَا","russian":"И клянусь луной, следующей за ним!"},{"number":3,"arabic":"وَٱلنَّهَارِ إِذَا جَلَّىٰهَا","russian":"И клянусь днем, который выявляет его [Солнца] свет!"},{"number":4,"arabic":"وَٱلَّيْلِ إِذَا يَغْشَىٰهَا","russian":"И клянусь ночью, которая скрывает его!"},{"number":5,"arabic":"وَٱلسَّمَآءِ وَمَا بَنَىٰهَا","russian":"И небом и Тем, Кто его соорудил!"},{"number":6,"arabic":"وَٱلْأَرْضِ وَمَا طَحَىٰهَا","russian":"И землей и Тем, Кто ее расстелил!"},{"number":7,"arabic":"وَنَفْسٍۢ وَمَا سَوَّىٰهَا","russian":"И душой [человеком] и Тем, Кто придал ему соразмерность"},{"number":8,"arabic":"فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا","russian":"и дал ему [человеку] понимание греха и набожности."},{"number":9,"arabic":"قَدْ أَفْلَحَ مَن زَكَّىٰهَا","russian":"Поистине, преуспел тот, кто очистил ее [душу],"},{"number":10,"arabic":"وَقَدْ خَابَ مَن دَسَّىٰهَا","russian":"и потерпел убыток тот, кто запятнал ее [грехами]."},{"number":11,"arabic":"كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ","russian":"Самудяне не поверили [своему пророку] из-за того, что перешли все границы [в своем неверии и грехах]."},{"number":12,"arabic":"إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا","russian":"И самый несчастный из них отправился [убивать верблюдицу]."},{"number":13,"arabic":"فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَٰهَا","russian":"И посланник Аллаха сказал им: «Не троньте верблюдицу и ее питье!»"},{"number":14,"arabic":"فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا","russian":"Но они не поверили ему [Салиху] и убили ее. Тогда Господь покарал их за этот грех всех без исключения."},{"number":15,"arabic":"وَلَا يَخَافُ عُقْبَٰهَا","russian":"И Он не боится последствий этого."}]},{"number":92,"name":"Аль-Ляйль","meaning":"Ночь","arabicName":"اللَّيۡلِ","ayahs":[{"number":1,"arabic":"وَٱلَّيْلِ إِذَا يَغْشَىٰ","russian":"Клянусь ночью, когда она покрывает [землю тьмой]!"},{"number":2,"arabic":"وَٱلنَّهَارِ إِذَا تَجَلَّىٰ","russian":"И клянусь днем, когда он раскрывает [мир своим светом]!"},{"number":3,"arabic":"وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ","russian":"И Тем, Кто сотворил мужчину и женщину!"},{"number":4,"arabic":"إِنَّ سَعْيَكُمْ لَشَتَّىٰ","russian":"Поистине, ваши стремления различны."},{"number":5,"arabic":"فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ","russian":"Тому, кто раздает [свое имущество на богоугодные дела] и проявляет богобоязненность,"},{"number":6,"arabic":"وَصَدَّقَ بِٱلْحُسْنَىٰ","russian":"кто верит в наилучшее [в положения Ислама],"},{"number":7,"arabic":"فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ","russian":"Мы облегчим путь к легкости [к Раю]."},{"number":8,"arabic":"وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ","russian":"А тому, кто был скуп и считал, что не нуждается [в Аллахе],"},{"number":9,"arabic":"وَكَذَّبَ بِٱلْحُسْنَىٰ","russian":"кто не верил в наилучшее,"},{"number":10,"arabic":"فَسَنُيَسِّرُهُۥ لِلْعُسْرَىٰ","russian":"Мы облегчим путь к тяжести [к Аду]."},{"number":11,"arabic":"وَمَا يُغْنِى عَنْهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ","russian":"И не спасет его богатство, когда он упадет [и умрет]."},{"number":12,"arabic":"إِنَّ عَلَيْنَا لَلْهُدَىٰ","russian":"Поистине, только Мы наставляем [на верный путь]."},{"number":13,"arabic":"وَإِنَّ لَنَا لَلْءَاخِرَةَ وَٱلْأُولَىٰ","russian":"И Нам, поистине, принадлежат вечная жизнь и жизнь земная."},{"number":14,"arabic":"فَأَنذَرْتُكُمْ نَارًۭا تَلَظَّىٰ","russian":"И Я предостерег вас от пылающего Ада."},{"number":15,"arabic":"لَا يَصْلَىٰهَآ إِلَّا ٱلْأَشْقَى","russian":"Войдет в него только самый несчастный,"},{"number":16,"arabic":"ٱلَّذِى كَذَّبَ وَتَوَلَّىٰ","russian":"который не поверил [пророку] и отвернулся [от истины]."},{"number":17,"arabic":"وَسَيُجَنَّبُهَا ٱلْأَتْقَى","russian":"Отдален [избавлен] будет от него [от Ада] самый богобоязненный,"},{"number":18,"arabic":"ٱلَّذِى يُؤْتِى مَالَهُۥ يَتَزَكَّىٰ","russian":"который тратит свое имущество [на благое], очищаясь [через это],"},{"number":19,"arabic":"وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعْمَةٍۢ تُجْزَىٰٓ","russian":"и любое благо он возмещает сполна,"},{"number":20,"arabic":"إِلَّا ٱبْتِغَآءَ وَجْهِ رَبِّهِ ٱلْأَعْلَىٰ","russian":"ища [этим] лишь довольства своего Всевышнего Господа."},{"number":21,"arabic":"وَلَسَوْفَ يَرْضَىٰ","russian":"И он будет доволен [наградой от Аллаха]."}]},{"number":93,"name":"Ад-Духа","meaning":"Утро","arabicName":"الضُّحَىٰ","ayahs":[{"number":1,"arabic":"وَٱلضُّحَىٰ","russian":"Клянусь поздним утром!"},{"number":2,"arabic":"وَٱلَّيْلِ إِذَا سَجَىٰ","russian":"И ночью, когда она темнеет!"},{"number":3,"arabic":"مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ","russian":"Не покинул тебя [о Мухаммад] твой Господь и не возненавидел."},{"number":4,"arabic":"وَلَلْءَاخِرَةُ خَيْرٌۭ لَّكَ مِنَ ٱلْأُولَىٰ","russian":"И, поистине, будущая [жизнь] лучше для тебя, чем нынешняя."},{"number":5,"arabic":"وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ","russian":"Господь твой обязательно воздаст тебе [в будущем благом], так что ты будешь доволен."},{"number":6,"arabic":"أَلَمْ يَجِدْكَ يَتِيمًۭا فَـَٔاوَىٰ","russian":"Разве Он не нашел тебя сиротой и не приютил?"},{"number":7,"arabic":"وَوَجَدَكَ ضَآلًّۭا فَهَدَىٰ","russian":"И Он нашел тебя потерявшим [верный] путь и наставил тебя [даровав знание законов Аллаха]."},{"number":8,"arabic":"وَوَجَدَكَ عَآئِلًۭا فَأَغْنَىٰ","russian":"И Он нашел тебя бедным и обогатил?"},{"number":9,"arabic":"فَأَمَّا ٱلْيَتِيمَ فَلَا تَقْهَرْ","russian":"Поэтому не обижай сироту."},{"number":10,"arabic":"وَأَمَّا ٱلسَّآئِلَ فَلَا تَنْهَرْ","russian":"И просящего не прогоняй."},{"number":11,"arabic":"وَأَمَّا بِنِعْمَةِ رَبِّكَ فَحَدِّثْ","russian":"И о милости твоего Господа – рассказывай!"}]},{"number":94,"name":"Аш-Шарх","meaning":"Раскрытие","arabicName":"الشَّرۡحِ","ayahs":[{"number":1,"arabic":"أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ","russian":"Разве Мы не раскрыли твою [о Мухаммад] грудь [твое сердце для света пророчества]?"},{"number":2,"arabic":"وَوَضَعْنَا عَنكَ وِزْرَكَ","russian":"[Разве мы] Не сняли с тебя бремя,"},{"number":3,"arabic":"ٱلَّذِىٓ أَنقَضَ ظَهْرَكَ","russian":"которое отягощало твою спину?"},{"number":4,"arabic":"وَرَفَعْنَا لَكَ ذِكْرَكَ","russian":"[Разве Мы не] Возвысили упоминание тебя?"},{"number":5,"arabic":"فَإِنَّ مَعَ ٱلْعُسْرِ يُسْرًا","russian":"И, поистине, за трудностью – облегчение."},{"number":6,"arabic":"إِنَّ مَعَ ٱلْعُسْرِ يُسْرًۭا","russian":"Поистине, за трудностью – облегчение."},{"number":7,"arabic":"فَإِذَا فَرَغْتَ فَٱنصَبْ","russian":"И если ты освободился [завершил дело], то трудись [возьмись за новое дело]."},{"number":8,"arabic":"وَإِلَىٰ رَبِّكَ فَٱرْغَب","russian":"И устремись к Господу своему."}]},{"number":95,"name":"Ат-Тин","meaning":"Смоковница","arabicName":"التِّينِ","ayahs":[{"number":1,"arabic":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ وَٱلتِّينِ وَٱلزَّيْتُونِ","russian":"Клянусь смоковницей и оливой!"},{"number":2,"arabic":"وَطُورِ سِينِينَ","russian":"И клянусь горой Синай!"},{"number":3,"arabic":"وَهَٰذَا ٱلْبَلَدِ ٱلْأَمِينِ","russian":"И этим безопасным городом [Меккой]!"},{"number":4,"arabic":"لَقَدْ خَلَقْنَا ٱلْإِنسَٰنَ فِىٓ أَحْسَنِ تَقْوِيمٍۢ","russian":"Мы, поистине, создали человека в совершенном виде."},{"number":5,"arabic":"ثُمَّ رَدَدْنَٰهُ أَسْفَلَ سَٰفِلِينَ","russian":"А затем Мы опустили его на самый низкий уровень,"},{"number":6,"arabic":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فَلَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۢ","russian":"кроме тех, кто уверовал и совершал благие дела. Им – нескончаемая награда."},{"number":7,"arabic":"فَمَا يُكَذِّبُكَ بَعْدُ بِٱلدِّينِ","russian":"Что же после этого не дает тебе [о неверующий человек] поверить в воздаяние?!"},{"number":8,"arabic":"أَلَيْسَ ٱللَّهُ بِأَحْكَمِ ٱلْحَٰكِمِينَ","russian":"Разве Аллах не является лучшим Судьей?"}]},{"number":96,"name":"Аль-Аляк","meaning":"Сгусток","arabicName":"العَلَقِ","ayahs":[{"number":1,"arabic":"ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ","russian":"Читай с именем твоего Господа, Который сотворил [все сущее]."},{"number":2,"arabic":"خَلَقَ ٱلْإِنسَٰنَ مِنْ عَلَقٍ","russian":"Сотворил человека из сгустка [крови]."},{"number":3,"arabic":"ٱقْرَأْ وَرَبُّكَ ٱلْأَكْرَمُ","russian":"Читай, ведь твой Господь – самый щедрый."},{"number":4,"arabic":"ٱلَّذِى عَلَّمَ بِٱلْقَلَمِ","russian":"Он научил [человека писать] пером –"},{"number":5,"arabic":"عَلَّمَ ٱلْإِنسَٰنَ مَا لَمْ يَعْلَمْ","russian":"научил человека тому, чего тот не знал."},{"number":6,"arabic":"كَلَّآ إِنَّ ٱلْإِنسَٰنَ لَيَطْغَىٰٓ","russian":"Но нет! [Он же неблагодарен] Человек переходит границы [дозволенного]."},{"number":7,"arabic":"أَن رَّءَاهُ ٱسْتَغْنَىٰٓ","russian":"[Переходит их] Потому что считает, будто не нуждается [в Аллахе]."},{"number":8,"arabic":"إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجْعَىٰٓ","russian":"Поистине, к твоему Господу – возвращение."},{"number":9,"arabic":"أَرَءَيْتَ ٱلَّذِى يَنْهَىٰ","russian":"Видел ли ты того, кто запрещает"},{"number":10,"arabic":"عَبْدًا إِذَا صَلَّىٰٓ","russian":"рабу [Аллаха] совершать намаз?"},{"number":11,"arabic":"أَرَءَيْتَ إِن كَانَ عَلَى ٱلْهُدَىٰٓ","russian":"Как думаешь, был ли он на верном пути [когда запрещал молиться]"},{"number":12,"arabic":"أَوْ أَمَرَ بِٱلتَّقْوَىٰٓ","russian":"или призывал к богобоязненности?"},{"number":13,"arabic":"أَرَءَيْتَ إِن كَذَّبَ وَتَوَلَّىٰٓ","russian":"Как думаешь, а не отверг ли он [истину] и не отвернулся ли [от нее]?"},{"number":14,"arabic":"أَلَمْ يَعْلَم بِأَنَّ ٱللَّهَ يَرَىٰ","russian":"Неужели он не знал, что Аллах видит [его и непременно воздаст ему за его дела]?"},{"number":15,"arabic":"كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ","russian":"Но нет! Если он не перестанет [так себя вести], то Мы схватим его за чуб,"},{"number":16,"arabic":"نَاصِيَةٍۢ كَٰذِبَةٍ خَاطِئَةٍۢ","russian":"чуб [обладатель которого] лживый и грешный."},{"number":17,"arabic":"فَلْيَدْعُ نَادِيَهُۥ","russian":"Пусть он зовет [на помощь] своих сообщников [родню и единомышленников]."},{"number":18,"arabic":"سَنَدْعُ ٱلزَّبَانِيَةَ","russian":"Мы же позовем стражей Ада!"},{"number":19,"arabic":"كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩","russian":"Нет же! Не подчиняйся ему [о Мухаммад], но совершай земные поклоны [усердно продолжай выполнять намазы] и приближайся к Аллаху [через поклонение Ему]."}]},{"number":97,"name":"Аль-Кадр","meaning":"Предустановление","arabicName":"القَدۡرِ","ayahs":[{"number":1,"arabic":"بِّسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةِ ٱلْقَدْرِ","russian":"Мы, поистине, низвели его [Куръан] в ночь Предустановления."},{"number":2,"arabic":"وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ","russian":"Откуда ты мог знать, что такое ночь Предустановления?"},{"number":3,"arabic":"لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ","russian":"Ночь Предустановления лучше тысячи месяцев."},{"number":4,"arabic":"تَنَزَّلُ ٱلْمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ","russian":"Ангелы и Дух [Джибриль] спускаются в нее [в эту ночь] с разрешения их Господа [на землю] со всеми Его повелениями."},{"number":5,"arabic":"سَلَٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ","russian":"Она благополучна до наступления рассвета."}]},{"number":98,"name":"Аль-Баййина","meaning":"Ясное знамение","arabicName":"البَيِّنَةِ","ayahs":[{"number":1,"arabic":"لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ","russian":"Неверующие из людей Писания и язычников не освободились [от неверия], пока к ним не пришло доказательство."},{"number":2,"arabic":"رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ","russian":"[Это доказательство –] Посланник от Аллаха, который читает очищенные [от лжи и искажений] страницы."},{"number":3,"arabic":"فِيهَا كُتُبٌۭ قَيِّمَةٌۭ","russian":"На них [этих страницах] – [содержание] правдивых [и священных] Книг."},{"number":4,"arabic":"وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ","russian":"Те, кому была дана Книга, разделились [на группы] лишь после того, как к ним пришло доказательство."},{"number":5,"arabic":"وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ","russian":"Им было приказано поклоняться Аллаху – искренне – только Ему одному, будучи верующими, а также [полноценно] совершать намаз и выплачивать закят. Это и есть правильная религия."},{"number":6,"arabic":"إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآ ۚ أُو۟لَٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ","russian":"Поистине, неверующие из людей Писания и язычников – в огне Ада. Они останутся там навечно. Они – худшие из творений."},{"number":7,"arabic":"إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ","russian":"Поистине, верующие, совершавшие праведные поступки, – лучшие из творений."},{"number":8,"arabic":"جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ","russian":"Их награда у их Господа – сады Рая, под которыми текут реки. Они останутся там навсегда, навечно. Аллах доволен ими, и они довольны Аллахом. Это [прекрасная награда] – тем, кто боялся своего Господа [избегая грехов]."}]},{"number":99,"name":"Аз-Залзаля","meaning":"Землетрясение","arabicName":"الزَّلۡزَلَةِ","ayahs":[{"number":1,"arabic":"إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا","russian":"Когда земля задрожит от сотрясений,"},{"number":2,"arabic":"وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا","russian":"и когда земля выбросит наружу свои тяжести [захороненные ценности и тела умерших],"},{"number":3,"arabic":"وَقَالَ ٱلْإِنسَٰنُ مَا لَهَا","russian":"и человек [в испуге] спросит: «Что с ней?»"},{"number":4,"arabic":"يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا","russian":"В тот день она [земля] расскажет свои истории [сообщит о хороших и дурных поступках, которые на ней совершались]."},{"number":5,"arabic":"بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا","russian":"[Расскажет] Потому что твой Господь внушит ей это."},{"number":6,"arabic":"يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَٰلَهُمْ","russian":"В тот день люди придут группами [к месту сбора], чтобы увидеть свои дела [воздаяние за них]."},{"number":7,"arabic":"فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ","russian":"Кто совершил добро весом с мельчайшую частицу, увидит его [награду за него]."},{"number":8,"arabic":"وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ","russian":"И кто совершил зло весом с мельчайшую частицу, увидит его [воздаяние за него]."}]},{"number":100,"name":"Аль-Адият","meaning":"Скачущие","arabicName":"العَادِيَاتِ","ayahs":[{"number":1,"arabic":"وَٱلْعَٰدِيَٰتِ ضَبْحًۭا","russian":"Клянусь мчащимися, тяжело дышащими [конями]!"},{"number":2,"arabic":"فَٱلْمُورِيَٰتِ قَدْحًۭا","russian":"И клянусь [конями] высекающими [копытами] искры!"},{"number":3,"arabic":"فَٱلْمُغِيرَٰتِ صُبْحًۭا","russian":"И [конями] нападающими на заре,"},{"number":4,"arabic":"فَأَثَرْنَ بِهِۦ نَقْعًۭا","russian":"которые окутывают [врагов густой] пылью,"},{"number":5,"arabic":"فَوَسَطْنَ بِهِۦ جَمْعًا","russian":"врываясь прямо в центр толпы."},{"number":6,"arabic":"إِنَّ ٱلْإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌۭ","russian":"Поистине, человек своему Господу неблагодарен."},{"number":7,"arabic":"وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ","russian":"И, поистине, он сам [человек] этому свидетель."},{"number":8,"arabic":"وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ","russian":"Ведь он страстно любит [земные] блага."},{"number":9,"arabic":"۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ","russian":"Разве он не знает, что, когда воскресят тех, кто в могилах,"},{"number":10,"arabic":"وَحُصِّلَ مَا فِى ٱلصُّدُورِ","russian":"и выявится все [тайное], что [было] в душах [людей],"},{"number":11,"arabic":"إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ","russian":"их Господь будет, поистине, знать обо всем [и воздаст им за их убеждения и дела]?!"}]},{"number":101,"name":"Аль-Кариа","meaning":"Бедствие","arabicName":"القَارِعَةِ","ayahs":[{"number":1,"arabic":"ٱلْقَارِعَةُ","russian":"Бедствие [Судный день]!"},{"number":2,"arabic":"مَا ٱلْقَارِعَةُ","russian":"Что такое Бедствие?"},{"number":3,"arabic":"وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ","russian":"Откуда ты узнал, что такое Бедствие?"},{"number":4,"arabic":"يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ","russian":"В тот день люди будут похожи на разлетевшихся мотыльков."},{"number":5,"arabic":"وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ","russian":"А горы станут [мягкими], как расчесанная шерсть."},{"number":6,"arabic":"فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ","russian":"Тот, чья чаша Весов окажется тяжелой,"},{"number":7,"arabic":"فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ","russian":"будет доволен своей жизнью."},{"number":8,"arabic":"وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ","russian":"Тому же, чья чаша Весов окажется легкой,"},{"number":9,"arabic":"فَأُمُّهُۥ هَاوِيَةٌۭ","russian":"прибежищем станет Ад."},{"number":10,"arabic":"وَمَآ أَدْرَىٰكَ مَا هِيَهْ","russian":"Откуда ты мог знать, что это такое?"},{"number":11,"arabic":"نَارٌ حَامِيَةٌۢ","russian":"Это – пылающий [жарко] Огонь!"}]},{"number":102,"name":"Ат-Такасур","meaning":"Приумножение","arabicName":"التَّكَاثُرِ","ayahs":[{"number":1,"arabic":"أَلْهَىٰكُمُ ٱلتَّكَاثُرُ","russian":"Отвлекло вас [от подчинения Аллаху] приумножение [земных благ]."},{"number":2,"arabic":"حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ","russian":"[Это продолжится до тех пор] Пока вы не посетите кладбища [умрете]."},{"number":3,"arabic":"كَلَّا سَوْفَ تَعْلَمُونَ","russian":"Но нет! В будущем вы узнаете!"},{"number":4,"arabic":"ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ","russian":"Еще раз нет! В будущем вы узнаете!"},{"number":5,"arabic":"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ","russian":"Нет! Если бы вы знали с убежденностью [о подстерегающей вас впереди опасности, вы бы не предпочли земное вечному]."},{"number":6,"arabic":"لَتَرَوُنَّ ٱلْجَحِيمَ","russian":"Клянусь, вы обязательно увидите Ад."},{"number":7,"arabic":"ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ","russian":"Затем вы обязательно увидите его собственными глазами!"},{"number":8,"arabic":"ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ","russian":"Затем в тот [Судный] день вас обязательно спросят о [земных] благах."}]},{"number":103,"name":"Аль-Аср","meaning":"Время","arabicName":"العَصۡرِ","ayahs":[{"number":1,"arabic":"وَٱلْعَصْرِ","russian":"Клянусь временем,"},{"number":2,"arabic":"إِنَّ ٱلْإِنسَٰنَ لَفِى خُسْرٍ","russian":"поистине, человек – в убытке,"},{"number":3,"arabic":"إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَتَوَاصَوْا۟ بِٱلْحَقِّ وَتَوَاصَوْا۟ بِٱلصَّبْرِ","russian":"кроме тех, которые уверовали, совершали благие поступки, заповедовали друг другу истину и заповедовали друг другу терпение."}]},{"number":104,"name":"Аль-Хумаза","meaning":"Хулитель","arabicName":"الهُمَزَةِ","ayahs":[{"number":1,"arabic":"وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ","russian":"Горе всякому клеветнику и обидчику,"},{"number":2,"arabic":"ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ","russian":"который копит богатство и пересчитывает его."},{"number":3,"arabic":"يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ","russian":"Он думает, что его богатство даст ему вечную жизнь."},{"number":4,"arabic":"كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ","russian":"Но нет! Он непременно будет ввергнут в аль-Хутама [Ад]."},{"number":5,"arabic":"وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ","russian":"Откуда ты узнал, что такое аль-Хутама?"},{"number":6,"arabic":"نَارُ ٱللَّهِ ٱلْمُوقَدَةُ","russian":"Это – неугасимый [адский] огонь Аллаха,"},{"number":7,"arabic":"ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ","russian":"который доходит до сердец."},{"number":8,"arabic":"إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ","russian":"Поистине, он сомкнется над ними,"},{"number":9,"arabic":"فِى عَمَدٍۢ مُّمَدَّدَةٍۭ","russian":"[подпертый] длинными столбами."}]},{"number":105,"name":"Аль-Филь","meaning":"Слон","arabicName":"الفِيلِ","ayahs":[{"number":1,"arabic":"أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَٰبِ ٱلْفِيلِ","russian":"Разве ты не видел, как поступил твой Господь с хозяевами слона?"},{"number":2,"arabic":"أَلَمْ يَجْعَلْ كَيْدَهُمْ فِى تَضْلِيلٍۢ","russian":"Разве Он не разрушил их злые умыслы?"},{"number":3,"arabic":"وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ","russian":"И Он наслал на них стаи птиц."},{"number":4,"arabic":"تَرْمِيهِم بِحِجَارَةٍۢ مِّن سِجِّيلٍۢ","russian":"Они закидали их камнями из обожженной глины."},{"number":5,"arabic":"فَجَعَلَهُمْ كَعَصْفٍۢ مَّأْكُولٍۭ","russian":"И Аллах превратил их в подобие жеваной травы."}]},{"number":106,"name":"Курайш","meaning":"Курайшиты","arabicName":"قُرَيۡشٍ","ayahs":[{"number":1,"arabic":"لِإِيلَٰفِ قُرَيْشٍ","russian":"Из-за безопасности курайшитов,"},{"number":2,"arabic":"إِۦلَٰفِهِمْ رِحْلَةَ ٱلشِّتَآءِ وَٱلصَّيْفِ","russian":"безопасности их во время зимних и летних поездок,"},{"number":3,"arabic":"فَلْيَعْبُدُوا۟ رَبَّ هَٰذَا ٱلْبَيْتِ","russian":"пусть же они поклоняются Господу этого Дома [Каабы],"},{"number":4,"arabic":"ٱلَّذِىٓ أَطْعَمَهُم مِّن جُوعٍۢ وَءَامَنَهُم مِّنْ خَوْفٍۭ","russian":"Который накормил их после голода и избавил их от страха."}]},{"number":107,"name":"Аль-Маун","meaning":"Милостыня","arabicName":"المَاعُونِ","ayahs":[{"number":1,"arabic":"أَرَءَيْتَ ٱلَّذِى يُكَذِّبُ بِٱلدِّينِ","russian":"Видел ли ты того, кто не верит в воздаяние [Судного дня]?"},{"number":2,"arabic":"فَذَٰلِكَ ٱلَّذِى يَدُعُّ ٱلْيَتِيمَ","russian":"И это – тот, кто гонит сироту"},{"number":3,"arabic":"وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ","russian":"и не побуждает накормить нищего."},{"number":4,"arabic":"فَوَيْلٌۭ لِّلْمُصَلِّينَ","russian":"И горе молящимся,"},{"number":5,"arabic":"ٱلَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ","russian":"которые небрежны к своим намазам,"},{"number":6,"arabic":"ٱلَّذِينَ هُمْ يُرَآءُونَ","russian":"которые совершают [намаз] напоказ"},{"number":7,"arabic":"وَيَمْنَعُونَ ٱلْمَاعُونَ","russian":"и препятствуют даже малому подаянию!"}]},{"number":108,"name":"Аль-Каусар","meaning":"Аль-Каусар","arabicName":"الكَوۡثَرِ","ayahs":[{"number":1,"arabic":"إِنَّآ أَعْطَيْنَٰكَ ٱلْكَوْثَرَ","russian":"Поистине, Мы даровали тебе аль-Кяусар."},{"number":2,"arabic":"فَصَلِّ لِرَبِّكَ وَٱنْحَرْ","russian":"Поэтому молись своему Господу и совершай жертвоприношение."},{"number":3,"arabic":"إِنَّ شَانِئَكَ هُوَ ٱلْأَبْتَرُ","russian":"Поистине, твой ненавистник сам окажется бездетным."}]},{"number":109,"name":"Аль-Кафирун","meaning":"Неверующие","arabicName":"الكَافِرُونَ","ayahs":[{"number":1,"arabic":"قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ","russian":"Скажи: «О неверующие!"},{"number":2,"arabic":"لَآ أَعْبُدُ مَا تَعْبُدُونَ","russian":"Я не поклоняюсь тому, чему вы поклоняетесь."},{"number":3,"arabic":"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ","russian":"А вы не поклоняетесь Тому, Кому поклоняюсь я."},{"number":4,"arabic":"وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ","russian":"Я не буду поклоняться тому, чему поклоняетесь вы."},{"number":5,"arabic":"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ","russian":"А вы не станете поклоняться Тому, Кому поклоняюсь я."},{"number":6,"arabic":"لَكُمْ دِينُكُمْ وَلِىَ دِينِ","russian":"Вам – ваша религия, а мне – моя!»"}]},{"number":110,"name":"Ан-Наср","meaning":"Помощь","arabicName":"النَّصۡرِ","ayahs":[{"number":1,"arabic":"إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ","russian":"Когда придет помощь Аллаха и победа,"},{"number":2,"arabic":"وَرَأَيْتَ ٱلنَّاسَ يَدْخُلُونَ فِى دِينِ ٱللَّهِ أَفْوَاجًۭا","russian":"ты увидишь, как люди обращаются в религию Аллаха толпами."},{"number":3,"arabic":"فَسَبِّحْ بِحَمْدِ رَبِّكَ وَٱسْتَغْفِرْهُ ۚ إِنَّهُۥ كَانَ تَوَّابًۢا","russian":"Возвеличивай же хвалой Господа своего и проси у Него прощения. Поистине, Он – Принимающий покаяние."}]},{"number":111,"name":"Аль-Масад","meaning":"Пальмовые волокна","arabicName":"المَسَدِ","ayahs":[{"number":1,"arabic":"تَبَّتْ يَدَآ أَبِى لَهَبٍۢ وَتَبَّ","russian":"Да отсохнут руки Абу Ляхаба, и сам он уже пропал."},{"number":2,"arabic":"مَآ أَغْنَىٰ عَنْهُ مَالُهُۥ وَمَا كَسَبَ","russian":"Не помогло ему его богатство и то, что приобрел [а именно – его сыновья]."},{"number":3,"arabic":"سَيَصْلَىٰ نَارًۭا ذَاتَ لَهَبٍۢ","russian":"Он попадет в Ад, полный огня."},{"number":4,"arabic":"وَٱمْرَأَتُهُۥ حَمَّالَةَ ٱلْحَطَبِ","russian":"А жена его – носильщица дров."},{"number":5,"arabic":"فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ","russian":"На шее у нее будет веревка из пальмовых волокон."}]},{"number":112,"name":"Аль-Ихляс","meaning":"Очищение веры","arabicName":"الإِخۡلَاصِ","ayahs":[{"number":1,"arabic":"قُلْ هُوَ ٱللَّهُ أَحَدٌ","russian":"Скажи: «Он – Аллах – Один."},{"number":2,"arabic":"ٱللَّهُ ٱلصَّمَدُ","russian":"Аллах Самодостаточен."},{"number":3,"arabic":"لَمْ يَلِدْ وَلَمْ يُولَدْ","russian":"Он не родил и не был рожден."},{"number":4,"arabic":"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ","russian":"И нет никого [и ничего] равного [и подобного] Ему»."}]},{"number":113,"name":"Аль-Фаляк","meaning":"Рассвет","arabicName":"الفَلَقِ","ayahs":[{"number":1,"arabic":"قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ","russian":"Скажи [о Мухаммад]: «Я прибегаю к защите Господа зари"},{"number":2,"arabic":"مِن شَرِّ مَا خَلَقَ","russian":"От зла всех Его творений."},{"number":3,"arabic":"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","russian":"И от зла ночи, когда она наступает."},{"number":4,"arabic":"وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ","russian":"И от зла дующих на узлы."},{"number":5,"arabic":"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","russian":"И от зла завистника, когда тот завидует»."}]},{"number":114,"name":"Ан-Нас","meaning":"Люди","arabicName":"النَّاسِ","ayahs":[{"number":1,"arabic":"قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ","russian":"Скажи: «Я прибегаю к защите Господа людей,"},{"number":2,"arabic":"مَلِكِ ٱلنَّاسِ","russian":"Властелина людей,"},{"number":3,"arabic":"إِلَٰهِ ٱلنَّاسِ","russian":"Бога людей,"},{"number":4,"arabic":"مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ","russian":"от зла искусителя, отступающего [при упоминании Аллаха],"},{"number":5,"arabic":"ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ","russian":"который нашептывает в сердца людей."},{"number":6,"arabic":"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","russian":"[Шайтан бывает] Из джиннов и людей»."}]}];
